#!/bin/bash# =============================================================================#  restore-postgres.sh#  PostgreSQL Restore Script â€” Sistema Nacional de CÃ³mputo Electoral Bolivia##  Restores a .dump file created by backup-postgres.sh.##  Usage:#    bash scripts/restore-postgres.sh ./postgres/backups/2025-10-19_18-00-00.dump##  WARNING: This will drop and recreate the target database.#           Use only for development/demo restore.# =============================================================================set -eCONTAINER="postgres-primary"DB_NAME="oep_oficial"DB_USER="oep_user"if [ -z "$1" ]; then  echo "Usage: bash scripts/restore-postgres.sh <backup-file.dump>"  echo "Example: bash scripts/restore-postgres.sh ./postgres/backups/2025-10-19_18-00-00.dump"  exit 1fiBACKUP_FILE="$1"if [ ! -f "$BACKUP_FILE" ]; then  echo "[ERROR] Backup file not found: $BACKUP_FILE"  exit 1fiecho "================================================="echo " OEP â€” PostgreSQL Restore"echo " Container   : $CONTAINER"echo " Database    : $DB_NAME"echo " Backup file : $BACKUP_FILE"echo "================================================="# Confirmread -p "[CONFIRM] This will DROP and recreate '$DB_NAME'. Continue? (y/N): " CONFIRMif [[ "$CONFIRM" != "y" && "$CONFIRM" != "Y" ]]; then  echo "[ABORT] Restore cancelled."  exit 0fiTEMP_FILE="/tmp/oep_restore_$(date +%s).dump"# Copy backup into containerecho "[INFO] Copying backup file to container..."docker cp "$BACKUP_FILE" "${CONTAINER}:${TEMP_FILE}"# Drop and recreate databaseecho "[INFO] Dropping and recreating database '$DB_NAME'..."docker exec "$CONTAINER" psql -U "$DB_USER" -d postgres \  -c "SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname = '${DB_NAME}' AND pid <> pg_backend_pid();" \  > /dev/null 2>&1 || truedocker exec "$CONTAINER" psql -U "$DB_USER" -d postgres \  -c "DROP DATABASE IF EXISTS ${DB_NAME};"docker exec "$CONTAINER" psql -U "$DB_USER" -d postgres \  -c "CREATE DATABASE ${DB_NAME} OWNER ${DB_USER};"# Run pg_restoreecho "[INFO] Running pg_restore..."docker exec "$CONTAINER" pg_restore \  -U "$DB_USER" \  -d "$DB_NAME" \  --no-owner \  --role="$DB_USER" \  "$TEMP_FILE"# Cleanupdocker exec "$CONTAINER" rm -f "$TEMP_FILE"echo ""echo "[OK] Restore complete. Verify with:"echo "     docker exec -it postgres-primary psql -U oep_user -d oep_oficial -c '\\dt'"echo "================================================="